def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    op = [h[1] for h in history]

    opp_c = op.count('C')
    opp_d = n - opp_c
    last_me = me[-1]
    last_op = op[-1]

    # Detect opponent's responsiveness to our last move.
    # If they mimic us, cooperation is stable and valuable.
    mirror = 0
    for i in range(1, n):
        if op[i] == me[i - 1]:
            mirror += 1
    mirror_rate = mirror / (n - 1) if n > 1 else 0.0

    # Detect immediate retaliation after our defection.
    retaliates = 0
    our_defs = 0
    for i in range(1, n):
        if me[i - 1] == 'D':
            our_defs += 1
            if op[i] == 'D':
                retaliates += 1
    retaliate_rate = retaliates / our_defs if our_defs > 0 else 1.0

    # Never-defect opponent: lock in mutual cooperation, probe only very rarely.
    if opp_d == 0:
        if n > 90 and rng.random() < 0.5:
            return 'D'
        if n > 40 and n % 23 == 0 and rng.random() < 0.1:
            return 'D'
        return 'C'

    # Almost-always-defect opponent: defend hard, try rare resets.
    if opp_c <= 1 and n >= 5:
        if n % 9 == 0 and rng.random() < 0.12:
            return 'C'
        return 'D'

    # If opponent is highly responsive to us, use firm reciprocity:
    # cooperate against cooperation, retaliate against defection.
    if mirror_rate > 0.6 or retaliate_rate > 0.6:
        if last_op == 'D':
            # If they retaliated after our defection, apologize with C once.
            if last_me == 'D' and our_defs > 0 and retaliates > 0:
                return 'C'
            return 'D'
        return 'C'

    # Mostly cooperative opponent: stay cooperative, punish sustained defection.
    if opp_d * 5 <= n:
        if last_op == 'D':
            # Count consecutive recent opponent defections.
            k = 0
            for i in range(n - 1, -1, -1):
                if op[i] == 'D':
                    k += 1
                else:
                    break
            if k >= 3:
                return 'D'
            # Forgive a single defection often to restore CC.
            if rng.random() < 0.45:
                return 'C'
            return 'D'
        # Cooperate, but occasionally test near the end.
        if n > 93 and rng.random() < 0.35:
            return 'D'
        return 'C'

    # Mostly defective opponent: defect mostly, probe occasionally.
    if opp_d * 3 >= n * 2:
        # If they just cooperated, exploit now then resume defense.
        if last_op == 'C' and last_me == 'D':
            return 'D'
        if last_op == 'C' and rng.random() < 0.7:
            return 'D'
        if n % 7 == 0 and rng.random() < 0.15:
            return 'C'
        return 'D'

    # Mixed opponent: forgiving tit-for-tat with defection-rate pressure.
    # Break DD loops by cooperating occasionally.
    if last_op == 'D' and last_me == 'D':
        k = 0
        for i in range(n - 1, -1, -1):
            if me[i] == 'D' and op[i] == 'D':
                k += 1
            else:
                break
        if k >= 2:
            if rng.random() < 0.5:
                return 'C'
            return 'D'
        if rng.random() < 0.2:
            return 'C'
        return 'D'

    if last_op == 'D' and last_me == 'C':
        # They exploited us; retaliate, but forgive sometimes if they've been decent.
        if opp_c * 3 >= n:
            if rng.random() < 0.3:
                return 'C'
        return 'D'

    if last_op == 'C' and last_me == 'D':
        return 'C'

    # Opponent cooperated last and so did we.
    if n > 95 and rng.random() < 0.25:
        return 'D'
    return 'C'
